'use strict';
// Personal learning is the active product. Existing community data is retained.
function learningData(){return state.learning||(state.learning={notes:[],mockPlan:null})}
function learningDraftKey(){return 'toolbox-journal-draft-v1:'+(cloudEnabled?cloudUser?.id||'signed-out':'local')}
function learningKeepDraft(){if(!learningDraft)return;try{localStorage.setItem(learningDraftKey(),JSON.stringify(learningDraft))}catch{learningMessage='Draft could not be backed up on this device. Copy your text before leaving.'}}
function learningClearDraft(){try{localStorage.removeItem(learningDraftKey())}catch{}}
function learningDate(d=new Date()){return [d.getFullYear(),String(d.getMonth()+1).padStart(2,'0'),String(d.getDate()).padStart(2,'0')].join('-')}
let learningDay='',learningWeek=0,learningTopic='',learningQuery='',learningNoteId=null,learningEditor=false,learningDraft=null,learningMessage='',learningOwner=null,learningDeleted=null;
let mockStep=0,mockDraft={track:'nw',functionId:0,items:20,minutes:30};
const learningFunctions={nw:['Navigation','Cargo handling & stowage','Ship operation & care for persons'],ew:['Marine engineering','Electrical, electronic & control engineering','Maintenance & repair','Ship operation & care for persons']};
const learningCompetencies={nw:[['Passage planning & position','Safe navigational watch','Radar & ARPA','ECDIS','Emergencies & distress','Search & rescue','Maritime English & SMCP','Visual signalling','Ship manoeuvring'],['Cargo loading, stowage, securing & unloading','Inspect cargo spaces, hatch covers & ballast tanks'],['Pollution prevention','Seaworthiness & stability','Fire prevention & firefighting','Life-saving appliances','Medical first aid','Legislative requirements','Leadership & teamwork','Personnel & ship safety']],ew:[['Safe engineering watch & resource management','Maritime English','Internal communications','Main & auxiliary machinery','Fuel, lubrication, ballast & pumping systems'],['Electrical, electronic & control systems','Maintenance & repair of electrical equipment'],['Tools for fabrication & repair','Hand tools & measuring instruments','Maintenance & repair of machinery'],['Pollution prevention','Seaworthiness & stability','Fire prevention & firefighting','Life-saving appliances','Medical first aid','Legislative requirements','Leadership & teamwork','Personnel & ship safety']]};
function learningWeekDays(offset=0,now=new Date()){const start=new Date(now.getFullYear(),now.getMonth(),now.getDate());start.setDate(start.getDate()-((start.getDay()+6)%7)+offset*7);return Array.from({length:7},(_,i)=>{const d=new Date(start);d.setDate(d.getDate()+i);return {key:learningDate(d),day:d.toLocaleDateString('en',{weekday:'short'}),number:d.getDate()}})}
function learningSave(change){const old=JSON.stringify(learningData());change(learningData());const bytes=new TextEncoder().encode(JSON.stringify(workspaceData())).length;if(bytes>650000){state.learning=JSON.parse(old);learningMessage='Your backup is nearly full. Export your notes and remove a photo before adding more.';return false}if(!persist()){state.learning=JSON.parse(old);learningMessage='Could not save on this device. Your draft is still open; copy it before leaving.';return false}learningMessage='';return true}
function learningNotes(){return learningData().notes||[]}
function learningStats(){const records=Object.values(state.review.records||{}),history=state.review.history||[];return {notes:learningNotes().length,answered:records.length,correct:records.filter(r=>r.correct).length,rounds:history.length,topics:Object.entries(learningNotes().reduce((m,n)=>(m[n.topic]=(m[n.topic]||0)+1,m),{})).sort((a,b)=>b[1]-a[1])}}
function learningToday(){const h=new Date().getHours(),g=h<12?'Good morning':h<18?'Good afternoon':'Good evening',s=learningStats(),active=state.review.session&&!state.review.session.done;app.innerHTML=`<section class="card learning-greeting"><div><time datetime="${learningDate()}">${new Date().toLocaleDateString('en',{weekday:'long',month:'short',day:'numeric',year:'numeric'})}</time><h1>${g}, ${esc((state.profile.name||'crew').split(' ')[0])}.</h1><p>${s.rounds?'One small session. One step closer.':'Your next rank starts with what you learn today.'}</p></div><img src="assets/toolbox-spanner.png" alt="Your seafarer study companion" width="110" height="110"></section><section class="card learning-primary"><span class="eyebrow">YOUR NEXT STEP</span><h2>${active?'Pick up where you left off.':'Make time for your next rank.'}</h2><p>${active?`${Object.keys(state.review.session.answers).length} of ${state.review.session.ids.length} answered`:'A short practice round is a good place to start.'}</p><button class="btn" data-learning="review">${active?'Continue review':'Start a review'} →</button></section><div class="learning-actions"><button class="card" data-learning="new"><b>＋ Write a journal</b><span>Keep something you learned.</span></button><button class="card" data-nav="learn"><b>▤ My library</b><span>${s.notes} personal ${s.notes===1?'entry':'entries'}</span></button></div>`}
function learningCalendar(){const days=learningWeekDays(learningWeek),notes=learningNotes();return `<section class="learning-calendar" aria-label="Journal calendar"><div class="learning-week-head"><button data-learning="weekPrevious" aria-label="Previous week">‹</button><strong>${days[0].key.slice(5)} — ${days[6].key.slice(5)}</strong><button data-learning="weekNext" aria-label="Next week">›</button><button data-learning="allDates" class="text-button">All dates</button></div><div class="learning-week">${days.map(d=>`<button data-learning-day="${d.key}" aria-pressed="${learningDay===d.key}" class="${learningDay===d.key?'selected':''} ${d.key===learningDate()?'today':''}" aria-label="${d.day} ${d.key}, ${notes.filter(n=>n.date===d.key).length} entries"><span>${d.day}</span><b>${d.number}</b><i aria-hidden="true">${notes.some(n=>n.date===d.key)?'•':'·'}</i></button>`).join('')}</div></section>`}
function learningLibrary(){const allNotes=learningNotes(),dated=allNotes.filter(n=>!learningDay||n.date===learningDay),topics=[...new Set(dated.map(n=>n.topic))].sort();const found=dated.filter(n=>(!learningTopic||n.topic===learningTopic)&&(!learningQuery||(n.title+' '+n.body+' '+n.topic).toLowerCase().includes(learningQuery.toLowerCase()))).sort((a,b)=>b.updatedAt.localeCompare(a.updatedAt));app.innerHTML=`<header class="learning-heading"><h1>My library</h1><button class="btn" data-learning="new">＋ Journal</button></header>${learningCalendar()}<label class="search">${icon('search')}<input id="learningSearch" type="search" value="${esc(learningQuery)}" placeholder="Search your notes" aria-label="Search personal library"></label><div class="learning-topic-grid">${topics.map(t=>`<button data-learning-topic="${esc(t)}" class="${learningTopic===t?'selected':''}" aria-pressed="${learningTopic===t}"><b>▤ ${esc(t)}</b><small>${dated.filter(n=>n.topic===t).length} entries</small></button>`).join('')}</div>${learningTopic?'<button class="text-button" data-learning="allTopics">All topics</button>':''}<p class="hint">${learningDay?esc(learningDay):'All dates'} · ${learningTopic?esc(learningTopic):'Choose a topic, or select a day to read its entries.'}</p><div class="learning-note-list">${learningDay||learningTopic||learningQuery?found.map(n=>`<button class="card learning-note-row" data-learning-note="${n.id}"><span><small>${esc(n.topic)} · ${esc(n.date)}</small><strong>${esc(n.title)}</strong><p>${esc(n.body.slice(0,100))}${n.body.length>100?'…':''}</p></span><b aria-hidden="true">›</b></button>`).join('')||'<section class="card"><h2>No entries here yet.</h2><button class="text-button" data-learning="new">Write a journal →</button></section>':!allNotes.length?'<section class="card"><h2>Your learning belongs here.</h2><p>Save your first observation or study note.</p><button class="btn" data-learning="new">Write my first entry</button></section>':''}</div>${learningDeleted?'<p role="status">Entry deleted. <button class="text-button" data-learning="undoDelete">Undo</button></p>':''}<button class="text-button" data-learning="export" ${allNotes.length?'':'disabled'}>Export my journal</button>`;const input=document.querySelector('#learningSearch');input.oninput=e=>{learningQuery=e.target.value;const pos=e.target.selectionStart;learningLibrary();const next=document.querySelector('#learningSearch');next.focus();next.setSelectionRange?.(pos,pos)}}
function learningOpenEditor(id=null,question=null){const n=learningNotes().find(n=>n.id===id);learningNoteId=null;learningEditor=true;learningDraft=n?{...n}:{id:crypto.randomUUID(),date:learningDate(),topic:learningTopic||'General',title:question?'Review Q'+question.number:'',body:question?question.question+'\n\nWhat I learned:\n':'',photo:'',reviewId:question?.id||null,createdAt:new Date().toISOString()};if(!id&&!question){try{const saved=JSON.parse(localStorage.getItem(learningDraftKey()));if(saved?.id&&typeof saved.body==='string')learningDraft=saved}catch{}}page='learn';render()}
function learningEditorView(){const n=learningDraft,topics=[...new Set(['General','Navigation','Marine engineering','Electrical & controls','Cargo operations','Safety','Maintenance & repair',...learningNotes().map(n=>n.topic)])];app.innerHTML=`<header class="learning-heading"><h1>${learningNotes().some(x=>x.id===n.id)?'Edit entry':'Learning journal'}</h1><button class="text-button" data-learning="cancel">Cancel</button></header><form class="card learning-editor" id="learningNoteForm"><label class="field">Topic<select name="topic">${topics.map(t=>`<option ${n.topic===t?'selected':''}>${esc(t)}</option>`).join('')}</select></label><label class="field">Custom topic (optional)<input name="customTopic" maxlength="60" value="" placeholder="Or create your own topic"></label><label class="field">Date<input type="date" name="date" required value="${esc(n.date)}"></label><label class="field">Title<input name="title" required maxlength="160" value="${esc(n.title)}" placeholder="What did you learn?"></label><label class="field">My note<textarea name="body" required maxlength="12000" rows="8" placeholder="An observation, a lesson, or something to remember…">${esc(n.body)}</textarea></label><label class="field">Photo (optional)<input id="learningPhoto" type="file" accept="image/jpeg,image/png,image/webp"></label><div id="learningPhotoPreview">${n.photo?`<img class="learning-photo" src="${esc(n.photo)}" alt="Attached journal photo"><button type="button" class="text-button" data-learning="removePhoto">Remove photo</button>`:''}</div><p class="hint">Private journal · one small photo per entry. Export regularly.</p><p id="learningNoteStatus" role="status">${esc(learningMessage)}</p><button class="btn" type="submit">Save entry →</button></form>`;const f=document.querySelector('#learningNoteForm');f.oninput=()=>{for(const k of ['date','title','body'])learningDraft[k]=f.elements[k].value;learningDraft.topic=f.elements.customTopic.value.trim()||f.elements.topic.value;learningKeepDraft()};f.onsubmit=e=>{e.preventDefault();f.oninput();const note={...learningDraft,title:learningDraft.title.trim(),body:learningDraft.body.trim(),updatedAt:new Date().toISOString()};if(!note.title||!note.body)return;if(learningSave(d=>{d.notes=d.notes||[];const i=d.notes.findIndex(x=>x.id===note.id);if(i<0)d.notes.push(note);else d.notes[i]=note})){learningClearDraft();learningEditor=false;learningDraft=null;learningNoteId=note.id;render()}else document.querySelector('#learningNoteStatus').textContent=learningMessage};document.querySelector('#learningPhoto').onchange=learningReadPhoto}
async function learningReadPhoto(e){const file=e.target.files?.[0];if(!file)return;const owner=learningOwner,draft=learningDraft;const status=document.querySelector('#learningNoteStatus');try{if(!['image/jpeg','image/png','image/webp'].includes(file.type)||file.size>10000000)throw Error('Choose a JPG, PNG or WebP under 10 MB.');const image=await createImageBitmap(file);const canvas=document.createElement('canvas'),scale=Math.min(1,640/Math.max(image.width,image.height));canvas.width=Math.round(image.width*scale);canvas.height=Math.round(image.height*scale);canvas.getContext('2d').drawImage(image,0,0,canvas.width,canvas.height);image.close();const data=canvas.toDataURL('image/jpeg',.55);if(data.length>90000)throw Error('This photo is too detailed. Try a smaller crop.');if(owner!==learningOwner||draft!==learningDraft)return;learningDraft.photo=data;learningKeepDraft();learningEditorView()}catch(error){if(owner===learningOwner&&draft===learningDraft)status.textContent=error.message}}
function learningReadNote(){const n=learningNotes().find(n=>n.id===learningNoteId);if(!n){learningNoteId=null;learningLibrary();return}app.innerHTML=`<header class="learning-heading"><button class="text-button" data-learning="library">← Library</button><button class="text-button" data-learning="edit">Edit</button></header><article class="card learning-reading"><small>${esc(n.topic)} · <time>${esc(n.date)}</time></small><h1>${esc(n.title)}</h1><p>${esc(n.body)}</p>${n.photo?`<img class="learning-photo" src="${esc(n.photo)}" alt="Journal attachment">`:''}</article><details class="card"><summary>Manage entry</summary><p>Delete removes this entry from your synced journal.</p><button class="text-button" data-learning="delete">Delete entry</button></details>`}
function learningProgress(){const s=learningStats(),next=s.answered<10?['First round',s.answered,10]:s.notes<5?['Learning keeper',s.notes,5]:['Building knowledge',s.answered,100],accuracy=s.answered?Math.round(s.correct/s.answered*100):0;app.innerHTML=`<header class="learning-heading"><h1>Your progress</h1></header><section class="card learning-primary"><span class="eyebrow">NEXT MILESTONE</span><h2>✦ ${next[0]}</h2><progress value="${Math.min(next[1],next[2])}" max="${next[2]}" aria-label="Next learning milestone"></progress><p>${next[1]} / ${next[2]} · keep building at your pace.</p></section><div class="learning-metrics"><div class="card"><b>${s.notes}</b><span>Notes written</span></div><div class="card"><b>${s.answered}</b><span>Questions practised</span></div><div class="card"><b>${accuracy}%</b><span>Latest-answer accuracy</span></div></div>${hubReviewProgress()}<section class="card"><h2>Most-written topics</h2>${s.topics.slice(0,5).map(([t,n])=>`<button class="profile-action" data-learning-topic="${esc(t)}"><strong>${esc(t)}</strong><span>${n}</span></button>`).join('')||'<p>Your topics appear after your first entry.</p>'}</section><details class="card"><summary>Top seafarers · planned</summary><p>A review-based Top 10 will open after server-verified scoring is ready. Personal notes remain private. Your practice scores are available above.</p></details>`}
function learningMockView(){const f=learningFunctions[mockDraft.track];app.innerHTML=`<header class="learning-heading"><button class="text-button" data-learning="mockBack">← Back</button><span>Mock Exam · Premium</span></header><progress value="${mockStep+1}" max="4" aria-label="Mock exam setup"></progress><section class="card learning-mock"><small>STEP ${mockStep+1} OF 4</small>${mockStep===0?`<h1>Which watch are you preparing for?</h1><div class="learning-actions">${['nw','ew'].map(t=>`<button class="card ${mockDraft.track===t?'selected':''}" data-mock-track="${t}" aria-pressed="${mockDraft.track===t}"><b>OIC ${t.toUpperCase()}</b><span>${t==='nw'?'Navigational':'Engineering'} watch</span></button>`).join('')}</div>`:mockStep===1?`<h1>Choose your function.</h1><label class="field">Function<select id="mockFunction">${f.map((name,i)=>`<option value="${i}" ${mockDraft.functionId===i?'selected':''}>${i+1}. ${name}</option>`).join('')}</select></label><ul class="learning-competencies">${learningCompetencies[mockDraft.track][mockDraft.functionId].map(c=>`<li>${esc(c)}</li>`).join('')}</ul>`:mockStep===2?`<h1>Set your practice pace.</h1><label class="field">Questions<select id="mockItems">${[10,20,40].map(n=>`<option ${n===mockDraft.items?'selected':''}>${n}</option>`).join('')}</select></label><label class="field">Time limit<select id="mockMinutes">${[15,30,60].map(n=>`<option value="${n}" ${n===mockDraft.minutes?'selected':''}>${n} minutes</option>`).join('')}</select></label><p>Timed practice will show your result after submission.</p>`:`<h1>Your exam practice plan.</h1><h2>OIC ${mockDraft.track.toUpperCase()}</h2><p><strong>${esc(f[mockDraft.functionId])}</strong><br>${mockDraft.items} questions · ${mockDraft.minutes} minutes</p><div class="note"><strong>Premium is not on sale yet.</strong><p>Competency-mapped questions, verified answer keys and payment access are still being prepared. This is a setup preview; no payment is taken.</p></div><button class="btn" data-learning="savePlan">Save my practice plan</button><p id="mockPlanStatus" role="status"></p><button class="text-button" data-learning="practice">Use free practice →</button>`}${mockStep<3?'<button class="btn" data-learning="mockNext">Continue →</button>':''}</section>`;if(mockStep===1)document.querySelector('#mockFunction').onchange=e=>{mockDraft.functionId=Number(e.target.value);learningMockView()};if(mockStep===2){document.querySelector('#mockItems').onchange=e=>mockDraft.items=Number(e.target.value);document.querySelector('#mockMinutes').onchange=e=>mockDraft.minutes=Number(e.target.value)}}
const learningOldReviewLanding=reviewLanding,learningOldTrack=reviewTrackView,learningOldQuestion=reviewQuestionView;
function learningMockButton(){return '<button class="card learning-premium" data-learning="mock"><span><small>PREMIUM · PREVIEW</small><strong>Mock exam</strong><span>Choose a function. Plan timed practice.</span></span><b>›</b></button>'}
reviewLanding=function(){learningOldReviewLanding();app.insertAdjacentHTML('beforeend',learningMockButton())};
reviewTrackView=function(){learningOldTrack();app.insertAdjacentHTML('beforeend',learningMockButton())};
reviewQuestionView=function(){learningOldQuestion();if(state.review.session&&!state.review.session.done)app.insertAdjacentHTML('beforeend','<button class="text-button" data-learning="questionNote">＋ Add a personal note</button>')};
profileSummary=function(){const p=state.profile,s=learningStats();app.innerHTML=`<section class="card profile-summary"><div class="profile-summary-head"><div class="qa-profile-title">${p.photo?`<img class="qa-avatar" src="${esc(p.photo)}" alt="Your profile photo">`:`<div class="qa-avatar">${esc((p.name||'Crew').slice(0,2).toUpperCase())}</div>`}<div><h1>${esc(p.name||'Crew')}</h1><p class="profile-rank">${esc(p.rank||'Rank not added')}</p><small>${esc(p.department||'')} · Self-reported</small></div></div><button class="profile-edit-small" id="editProfile">Edit</button></div><h2>About me</h2><p>${esc(p.bio||'No bio added yet.')}</p><div class="profile-email"><strong>Email · private</strong>${esc(p.email||'')}</div></section><section class="card"><h2>My learning</h2><p>${s.notes} journal entries · ${s.rounds} review rounds</p><button class="text-button" data-nav="progress">View progress →</button></section>${profileLinks()}`;document.querySelector('#editProfile').onclick=()=>{editingProfile=true;render()}};
const learningOldPrivacy=privacyView;
privacyView=function(){learningOldPrivacy();app.insertAdjacentHTML('afterbegin','<section class="card"><h2>Your journal is private</h2><p>Saved notes and attached journal photos are stored in your private workspace when cloud sync is connected. They are not added to public question feeds or rankings. Account-specific copies and unfinished drafts can remain on this browser after signing out. Do not use a shared device for confidential notes.</p></section>')};
const learningOldAccess=accessUI;
accessUI=function(){learningOldAccess();const refresh=app.querySelector('[data-cloud="refresh"]');if(refresh)refresh.textContent='Refresh account';const copy=app.querySelector('#cloudSyncState')?.nextElementSibling;if(copy)copy.textContent='Your journal, review scores and preferences are private. Pending changes have an account-specific recovery copy on this device.'};
cloudTerms=function(){app.innerHTML='<article class="card"><button class="text-button" data-cloud="signin">← Sign in</button><h1>Learn with care.</h1><p>Toolbox is a personal review and learning journal. It does not replace approved training, vessel procedures or responsible officers. Practice keys are provisional and may contain mistakes.</p><p>Your personal journal is private. Upload only content you are permitted to store. Do not include confidential vessel or personal documents.</p><p>Scores and badges do not establish professional competence. Premium mock exams are a setup preview and are not on sale.</p></article>'};
const learningOldRenderNav=renderNav;
renderNav=function(){learningOldRenderNav();for(const id of ['desktopNav','mobileNav']){const home=document.getElementById(id).querySelector('[data-nav="home"] span');if(home){home.textContent='Today';const parent=home.parentElement;if(parent)parent.innerHTML=icon('home')+'<span>Today</span>'}}};
const learningOldMatches=hubAppMatches;
hubAppMatches=function(text){const words=hubSearchNormal(text).split(' ').filter(Boolean),base=learningOldMatches(text).filter(r=>!['Question','Topic'].includes(r.kind)&&!['leaderboard','community'].includes(r.page));return [...base,...(words.length?learningNotes().filter(n=>words.every(w=>hubSearchNormal(n.title+' '+n.body+' '+n.topic).includes(w))).map(n=>({kind:'Note',title:n.title,id:n.id})):[])].slice(0,50)};
const learningOldOpenResult=hubOpenAppResult;
hubOpenAppResult=function(i){const r=hubSearchItems[i];if(r?.kind==='Note'){document.querySelector('#hubAppSearch')?.close();learningNoteId=r.id;learningEditor=false;page='learn';render()}else learningOldOpenResult(i)};
const learningOldNav=nav;
nav=function(p){if(state.hubOnboardingCompleted){if(p==='mock'){page='mock';render();return}if(['ask','detail','leaderboard','explore','activity','badges'].includes(p))p='home';if(p==='learn'){learningNoteId=null;learningEditor=false}}learningOldNav(p)};
const learningOldRender=render;
render=function(){const owner=cloudEnabled?cloudUser?.id:'local';if(owner!==learningOwner){learningOwner=owner;learningDay='';learningTopic='';learningQuery='';learningEditor=false;learningDraft=null;learningNoteId=null;learningDeleted=null;mockStep=0;learningMessage=''}if(!state.hubOnboardingCompleted||(cloudEnabled&&(!cloudReady||cloudRecovery||cloudReviewRecovery))){learningOldRender();return}if(['ask','detail','leaderboard','activity','badges','explore'].includes(page))page='home';if(['home','learn','progress','mock'].includes(page)){applyTheme();document.body.classList.remove('intro-mode');app.classList.remove('setup-view');renderNav();document.querySelector('#sectionName').textContent=({home:'Today',learn:'My library',progress:'Progress',mock:'Mock exam'})[page];if(page==='home')learningToday();if(page==='learn'){if(learningEditor)learningEditorView();else if(learningNoteId)learningReadNote();else learningLibrary()}if(page==='progress')learningProgress();if(page==='mock')learningMockView();uiHeader();hubRecordRoute();hubRefreshNavigation();hubCompactScreen();hubApplyBrand();cloudSyncNotice();saveLastView();}else learningOldRender();document.title='Toolbox | Review & Learning Journal';for(const image of app.querySelectorAll('img[src="assets/seafarer-mascot.webp"]'))image.src='assets/toolbox-spanner.png'};
// Load only the current profile. Public feeds are dormant, with no table-wide reads.
readCloudFeed=async function(){const owner=cloudUser?.id,epoch=cloudSessionEpoch;if(!owner)return;const {data:p,error}=await hubClient.from('hub_profiles').select('*').eq('id',owner).maybeSingle();if(error)throw error;const url=p?.photo?await signedPhoto(p.photo):'';if(owner!==cloudUser?.id||epoch!==cloudSessionEpoch)return;if(p){state.profile={...p,email:cloudUser.email||'',photo:url,photoPath:p.photo};if(cloudProfileDraft)state.profile={...state.profile,...cloudProfileDraft.fields,photo:cloudProfileDraft.photo||'',photoPath:cloudProfileDraft.photoPath||''}}cloudQuestions=[]};
hubDestinations.splice(0,hubDestinations.length,...[['home','Today','Journal review continue learning'],['learn','Library','Personal notes calendar journal topics'],['review','Review','OIC NW OIC EW practice quiz'],['progress','Progress','Scores notes milestones'],['profile','Profile','Name rank bio photo'],['settings','Settings','Appearance dark light'],['access','Account & storage','Sync backup'],['help','Help','Instructions'],['about','About','Creator'],['feedback','Feedback','Support'],['privacy','Privacy policy','Data protection']]);
hubQuickGuides.home=['Today',['Start or resume a short review.','Write a private journal entry about what you learned.']];hubQuickGuides.learn=['My library',['Tap a date to see that day’s entries. Use arrows to change weeks.','Choose a topic to read its notes, or search your library.','Use Edit to change an entry. Export keeps a separate copy.']];hubQuickGuides.progress=['Progress',['See your review scores and personal learning milestones.','Note totals count entries, not professional competence.']];
welcomeView=function(){app.innerHTML='<section class="card short-welcome"><span class="welcome-step">1 OF 3 · WELCOME ABOARD</span><img src="assets/toolbox-spanner.png" alt="Your seafarer study companion"><h1>Hi, I’m JV.<br>A seafarer, just like you.</h1><p>Preparing for your next rank takes steady effort. I built <strong>Toolbox</strong> to help you practise, record what you learn, and find it again.</p><p>A little progress today. Something to build on tomorrow.</p><div class="short-signature">— JV Ursal</div><button class="btn" data-nav="gettingstarted">Let’s get started →</button></section>'};
gettingStartedView=function(){app.innerHTML='<section class="card getting-started"><span class="welcome-step">2 OF 3 · GETTING STARTED</span><h1>Your next rank, one step at a time.</h1><div class="getting-started-steps"><p><strong>Review</strong> — take a short practice round.</p><p><strong>Journal</strong> — save something you learned.</p><p><strong>Library</strong> — revisit your notes by date or topic.</p><p><strong>Progress</strong> — see your scores and milestones.</p></div><button class="btn" id="beginProfile">Set up my profile →</button></section>';document.querySelector('#beginProfile').onclick=()=>{state.hubTourCompleted=true;persist();nav('setup')}};
helpUI=function(){app.innerHTML='<section class="card"><h1>Review. Record. Move up.</h1><p>Start a review from Today. Use Write a journal to keep a personal note. Your Library organises entries by date and topic.</p><p>Practice scores appear in Progress. Use ? for help on each screen. Your account and saving status are in Profile → Settings → Account & storage.</p><button class="btn" data-nav="home">Open Today →</button></section>'};
aboutUI=function(){app.innerHTML='<section class="card"><img src="assets/hub-logo.svg" width="64" height="64" alt="Toolbox"><h1>Toolbox</h1><p>A personal review and learning journal for seafarers preparing for their next rank.</p><p>Created by JV Ursal · <strong>Bulletproof Seafarers</strong>.</p><p>Practice keys are provisional. This app is a learning aid, not an official examination or training record.</p><button class="btn" data-nav="feedback">Share feedback</button></section>'};
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b||b.disabled)return;const d=b.dataset;if(d.learningDay){learningDay=d.learningDay;learningTopic='';learningNoteId=null;render();return}if(d.learningTopic){learningTopic=d.learningTopic;learningDay='';learningNoteId=null;learningEditor=false;nav('learn');return}if(d.learningNote){learningNoteId=d.learningNote;render();return}if(d.mockTrack){mockDraft.track=d.mockTrack;mockDraft.functionId=0;render();return}if(!d.learning)return;switch(d.learning){case'new':learningOpenEditor();return;case'review':if(state.review.session&&!state.review.session.done){state.review.track=state.review.session.track;reviewScreen='round';reviewReadSet=null}nav('review');return;case'questionNote':learningOpenEditor(null,reviewIndex.get(state.review.session.ids[state.review.session.index]));return;case'weekPrevious':learningWeek--;break;case'weekNext':learningWeek++;break;case'allDates':learningDay='';break;case'allTopics':learningTopic='';break;case'library':learningNoteId=null;break;case'edit':learningOpenEditor(learningNoteId);return;case'cancel':learningKeepDraft();learningEditor=false;learningDraft=null;break;case'removePhoto':learningDraft.photo='';learningKeepDraft();break;case'delete':{const removed=learningNotes().find(n=>n.id===learningNoteId);if(learningSave(x=>{x.notes=x.notes.filter(n=>n.id!==learningNoteId)})){learningDeleted=removed;learningNoteId=null}break}case'undoDelete':if(learningDeleted&&learningSave(x=>{if(!x.notes.some(n=>n.id===learningDeleted.id))x.notes.push(learningDeleted)}))learningDeleted=null;break;case'mock':mockStep=0;nav('mock');return;case'mockNext':mockStep=Math.min(3,mockStep+1);break;case'mockBack':if(mockStep)mockStep--;else nav('review');break;case'practice':nav('review');return;case'savePlan':if(learningSave(x=>{x.mockPlan={...mockDraft}}))document.querySelector('#mockPlanStatus').textContent='Plan saved. Free practice is available now.';else document.querySelector('#mockPlanStatus').textContent=learningMessage;return;case'export':{const blob=new Blob([JSON.stringify({app:'Toolbox',version:1,notes:learningNotes()},null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='Toolbox-journal-'+learningDate()+'.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);return}}render()});
const learningOldSnapshot=hubRouteSnapshot,learningOldRouteKey=hubRouteKey,learningOldBack=hubBack;
hubRouteSnapshot=function(){return {...learningOldSnapshot(),learningContext:{day:learningDay,week:learningWeek,topic:learningTopic,note:learningNoteId,editor:learningEditor,mockStep}}};
hubRouteKey=function(r){return learningOldRouteKey(r)+JSON.stringify(r.learningContext)};
hubBack=function(){const r=hubRouteHistory.at(-2);if(r?.learningContext){const x=r.learningContext;learningDay=x.day;learningWeek=x.week;learningTopic=x.topic;learningNoteId=x.note;learningEditor=x.editor&&!!learningDraft;mockStep=x.mockStep}return learningOldBack()};
const learningOldSwipe=hubSwipeTarget;
hubSwipeTarget=function(direction){if(direction==='left'&&(learningEditor||learningNoteId||page==='mock'))return null;return learningOldSwipe(direction)};
render();
